<?php

use Symfony\Component\Process\Process;

/*
 * R6-B6 isolated restore drill — the STRUCTURED backup format (review findings PR-6, PR-5, PR-8, PR-3).
 *
 * The drill accepts only a pg_dump 16 custom-format archive. These tests run the strict TOC validator and the strict
 * data-section counter over the TEXT forms of synthetic fixture archives (tests/Fixtures/restore-drill, generated by
 * make-archives.sh), so they need no PostgreSQL binary. The real pg_restore path runs in RestoreDrillSandboxRuntimeTest.
 */

function rdaLib(string $script, array $env = []): array
{
    $process = new Process(['bash', '-c', '. "$LIB/restore-archive.sh"; '.$script], null, array_merge([
        'LIB' => base_path('scripts/lib'), 'FX' => base_path('tests/Fixtures/restore-drill'), 'PATH' => getenv('PATH'),
    ], $env));
    $process->run();

    return ['exit' => (int) $process->getExitCode(), 'out' => trim($process->getOutput()), 'err' => $process->getErrorOutput()];
}

function rdaTemp(string $content): string
{
    $file = tempnam(sys_get_temp_dir(), 'rda');
    file_put_contents($file, $content);

    return $file;
}

it('accepts the synthetic application archive and lists every table that carries data (PR-6)', function () {
    $run = rdaLib('dms_archive_toc_validate "$FX/clean.toc" "app_runtime dms_owner" "" && printf "%s\n" "${DMS_ARCHIVE_DATA_TABLES[@]}" && echo "owners=${!DMS_ARCHIVE_OWNERS[*]}"');

    expect($run['exit'])->toBe(0, $run['out'])
        ->and($run['out'])->toContain("public.items\npublic.migrations")
        ->and($run['out'])->toContain('owners=app_runtime');
});

it('refuses, fail closed, every archive outside the structure the application produces', function (string $fixture, string $roles, string $exts, string $message) {
    $run = rdaLib('dms_archive_toc_validate "$FX/'.$fixture.'.toc" "'.$roles.'" "'.$exts.'"');

    expect($run['exit'])->toBe(1)
        ->and($run['out'])->toContain($message);
})->with([
    'a row-level security policy (type outside the allowlist)' => ['rls', 'app_runtime dms_owner', '', 'entry type outside the allowlist: ROW'],
    'a second schema' => ['otherschema', 'app_runtime dms_owner', '', 'entry type outside the allowlist: SCHEMA'],
    'a table name with a newline' => ['weirdname', 'app_runtime dms_owner', '', "TABLE name 'we ird' is not a plain lowercase identifier"],
    'an extension outside the allowlist (PR-8)' => ['ext', 'app_runtime', '', "extension 'pgcrypto', which is not in the allowlist (PR-8)"],
    'an owner the manifest does not list (D-Q6-a)' => ['r6owner', 'app_runtime', '', "makes 'dms_owner' an owner and the manifest does not list it (D-Q6-a)"],
]);

it('accepts an allowlisted extension and records both owners of a two-owner archive', function () {
    $ext = rdaLib('dms_archive_toc_validate "$FX/ext.toc" "app_runtime" "pgcrypto"');
    $owners = rdaLib('dms_archive_toc_validate "$FX/r6owner.toc" "app_runtime dms_owner" "" && echo "${!DMS_ARCHIVE_OWNERS[*]}" | tr " " "\n" | sort | paste -sd, -');

    expect($ext['exit'])->toBe(0, $ext['out'])
        ->and($owners['out'])->toBe('app_runtime,dms_owner');
});

it('refuses a TOC that is malformed, not custom format, not from PostgreSQL 16, or inconsistent', function (string $mutation, string $message) {
    $toc = (string) file_get_contents(base_path('tests/Fixtures/restore-drill/clean.toc'));
    $file = rdaTemp(match ($mutation) {
        'not custom' => str_replace(';     Format: CUSTOM', ';     Format: TAR', $toc),
        'older server' => str_replace(';     Dumped from database version: 16.', ';     Dumped from database version: 15.', $toc),
        'garbage line' => $toc."this is not a TOC line\n",
        'unknown type' => $toc."9999; 0 0 EVENT TRIGGER - evil app_runtime\n",
        'table without data' => $toc."9998; 1259 99999 TABLE public ghost app_runtime\n",
        'duplicate data' => $toc.preg_replace('/^.*TABLE DATA public items.*$/m', '$0', (string) collect(explode("\n", $toc))->first(fn ($l) => str_contains($l, 'TABLE DATA public items')))."\n",
        'non-printable' => $toc."9997; 0 0 COMMENT public TABLE items \x1b[31m app_runtime\n",
    });
    $run = rdaLib('dms_archive_toc_validate "$F" "app_runtime" ""', ['F' => $file]);
    unlink($file);

    expect($run['exit'])->toBe(1)
        ->and($run['out'])->toContain($message);
})->with([
    ['not custom', 'not a custom-format archive'],
    ['older server', 'not dumped by pg_dump 16 from PostgreSQL 16'],
    ['garbage line', 'is malformed'],
    ['unknown type', 'entry type outside the allowlist: EVENT'],
    ['table without data', 'table public.ghost has no data entry'],
    ['duplicate data', 'data for public.items appears twice'],
    ['non-printable', 'is not printable'],
]);

it('counts every table\'s rows from the data section, whatever the values look like (PR-5, PR-6)', function () {
    // The fixture's items hold 'COPY x FROM stdin;', a newline, a lone '\.' and a fake '-- Name:' header as VALUES.
    $run = rdaLib('dms_archive_count_program > "$T"; awk -f "$T" "$FX/clean.data"', ['T' => tempnam(sys_get_temp_dir(), 'rdaw')]);

    expect($run['exit'])->toBe(0, $run['out'])
        ->and($run['out'])->toBe("public.items\t4\npublic.migrations\t2");
});

it('refuses a data section that is not exactly pg_restore\'s framing', function (string $mutation, string $message) {
    $data = (string) file_get_contents(base_path('tests/Fixtures/restore-drill/clean.data'));
    $file = rdaTemp(match ($mutation) {
        'injected statement' => str_replace('COPY public.items', "DROP TABLE public.migrations;\nCOPY public.items", $data),
        'unterminated block' => substr_replace($data, "\n", (int) strpos($data, "\n\\.\n"), strlen("\n\\.\n")),
        'field count' => str_replace("1\tsynthetic_one", "1\tsynthetic_one\textra", $data),
        'no envelope' => preg_replace('/^\\\\restrict .*$/m', '', $data),
        'after the envelope' => $data."SELECT 1;\n",
    });
    $run = rdaLib('dms_archive_count_program > "$W"; awk -f "$W" "$F"', ['F' => $file, 'W' => tempnam(sys_get_temp_dir(), 'rdaw')]);
    unlink($file);

    expect($run['exit'])->toBe(1)
        ->and($run['out'])->toContain('ERROR '.$message);
})->with([
    ['injected statement', 'unexpected line in the data section'],
    ['unterminated block', 'row field count differs'],
    ['field count', 'row field count differs'],
    ['no envelope', 'data stream does not open with'],
    ['after the envelope', 'content after'],
]);

it('matches counts to the TOC in order and builds one canonical per-table digest (PR-5)', function () {
    $ok = rdaLib('dms_archive_toc_validate "$FX/clean.toc" "app_runtime" "" > /dev/null; printf "public.items\t4\npublic.migrations\t2\n" > "$C"; dms_archive_counts_check "$C" && dms_archive_digest "$C"', ['C' => tempnam(sys_get_temp_dir(), 'rdac')]);
    $swapped = rdaLib('dms_archive_toc_validate "$FX/clean.toc" "app_runtime" "" > /dev/null; printf "public.migrations\t2\npublic.items\t4\n" > "$C"; dms_archive_counts_check "$C"', ['C' => tempnam(sys_get_temp_dir(), 'rdac')]);
    $missing = rdaLib('dms_archive_toc_validate "$FX/clean.toc" "app_runtime" "" > /dev/null; printf "public.items\t4\n" > "$C"; dms_archive_counts_check "$C"', ['C' => tempnam(sys_get_temp_dir(), 'rdac')]);

    expect($ok['out'])->toBe(hash('sha256', "public\titems\t4\npublic\tmigrations\t2\n"))
        ->and($swapped['exit'])->toBe(1)
        ->and($swapped['out'])->toContain('data block 0 is public.migrations, the TOC says public.items')
        ->and($missing['out'])->toContain('2 TABLE DATA entries but 1 data blocks');
});

it('inspects the untrusted archive only inside a hardened, network-less unit', function () {
    $code = (string) file_get_contents(base_path('scripts/lib/restore-archive.sh'));

    expect($code)->toContain('-p PrivateNetwork=yes')
        ->and($code)->toContain('-p RestrictAddressFamilies=AF_UNIX')
        ->and($code)->toContain('-p Type=oneshot -p TimeoutStartSec=300 -p MemoryMax=512M')
        ->and($code)->toContain('BindReadOnlyPaths=${archive}:/opt/dmsinspect/archive.dump')
        ->and($code)->toContain('-p "NoExecPaths=/ /tmp /var/tmp"')
        ->and($code)->toContain('| head -c 12582912 >');
});

it('ships the fixture archives with their generator and digests (synthetic data only)', function () {
    $sums = (string) file_get_contents(base_path('tests/Fixtures/restore-drill/SHA256SUMS'));
    foreach (['clean', 'bomb', 'rls', 'ext', 'weirdname', 'otherschema', 'metabody', 'r6owner'] as $f) {
        $file = base_path("tests/Fixtures/restore-drill/{$f}.dump");
        expect($sums)->toContain(hash_file('sha256', $file)."  {$f}.dump");
    }
});
